import type { FileNode, FileStatus } from "./types";

/**
 * 扁平变更路径列表 → 文件树。
 * agent 后端通常直接给出 git 变更列表（"src/ui/button.tsx" + status），
 * 这里按路径段建树：目录优先、同级字母序，文件继承传入 status。
 */
export function buildFileTree(files: Array<{ path: string; status?: FileStatus }>): FileNode[] {
  type Draft = FileNode & { childrenMap?: Map<string, Draft> };

  const root: Draft = { path: "", type: "dir", children: [], childrenMap: new Map() };

  for (const f of files) {
    const segs = f.path.split("/").filter(Boolean);
    let cur = root;
    segs.forEach((seg, i) => {
      const isLeaf = i === segs.length - 1;
      const path = segs.slice(0, i + 1).join("/");
      let next = cur.childrenMap!.get(seg);
      if (!next) {
        next = isLeaf
          ? { path, type: "file", status: f.status }
          : { path, type: "dir", children: [], childrenMap: new Map() };
        cur.childrenMap!.set(seg, next);
        cur.children!.push(next);
      } else if (isLeaf && next.type !== "dir") {
        next.status = f.status; // 重复路径以最后一次为准
      }
      cur = next;
    });
  }

  const sortRec = (nodes: Draft[]): Draft[] => {
    nodes.sort((a, b) => {
      const ad = a.type === "dir" || (a.children?.length ?? 0) > 0 ? 1 : 0;
      const bd = b.type === "dir" || (b.children?.length ?? 0) > 0 ? 1 : 0;
      if (ad !== bd) return bd - ad; // 目录在前
      return a.path.split("/").pop()!.localeCompare(b.path.split("/").pop()!);
    });
    for (const n of nodes) if (n.children?.length) sortRec(n.children as Draft[]);
    return nodes;
  };

  const clean = (nodes: Draft[]): FileNode[] =>
    nodes.map(({ childrenMap, children, ...rest }) => {
      const out: FileNode = rest;
      if (children?.length) out.children = clean(children);
      return out;
    });

  return clean(sortRec(root.children!));
}

/** 深度优先展开可见行（level 从 1 起） */
export interface FlatRow {
  node: FileNode;
  level: number;
  isDir: boolean;
  expanded: boolean;
}

export function flattenTree(tree: FileNode[], isExpanded: (p: string) => boolean): FlatRow[] {
  const out: FlatRow[] = [];
  const walk = (nodes: FileNode[], level: number) => {
    for (const node of nodes) {
      const isDir = node.type === "dir" || (node.children?.length ?? 0) > 0;
      const expanded = isDir && isExpanded(node.path);
      out.push({ node, level, isDir, expanded });
      if (expanded && node.children?.length) walk(node.children, level + 1);
    }
  };
  walk(tree, 1);
  return out;
}

/** 目录下（递归）带变更标记的文件数，用于目录行的计数徽章 */
export function countStatus(node: FileNode): number {
  if (!node.children?.length) return node.status ? 1 : 0;
  return node.children.reduce((sum, c) => sum + countStatus(c), 0);
}

/** VaFileTree 的类型定义 */

export type FileStatus = "modified" | "added" | "deleted" | "untracked";

/** 状态单字母徽章 */
export const FILE_STATUS_LABEL: Record<FileStatus, string> = {
  modified: "M",
  added: "A",
  deleted: "D",
  untracked: "U",
};

export interface FileNode {
  /** 完整路径（默认作为 id 与选中值） */
  path: string;
  /** 节点类型；缺省按有无 children 推断 */
  type?: "file" | "dir";
  /** 变更标记（目录上通常不设，由子节点聚合展示计数） */
  status?: FileStatus;
  children?: FileNode[];
}

export interface FileTreeProps {
  /** 顶层节点：根目录单元素，或直接的文件/目录列表 */
  tree: FileNode[];
  /** 初始展开深度：0 = 只显示第一层，默认 1 */
  defaultExpandDepth?: number;
  /** 受控选中路径（配合 @update:selected 实现 v-model:selected） */
  selected?: string;
  /** 非受控默认选中 */
  defaultSelected?: string;
  /** 头部统计条文案；空字符串隐藏 */
  title?: string;
  /** 内容区最大高度 px，超出滚动 */
  maxHeight?: number;
}

export interface FileTreeEvents {
  "update:selected": [path: string | undefined];
  select: [node: FileNode];
  toggle: [node: FileNode, expanded: boolean];
}

import { computed, ref, watch } from "vue";
import type { FileTreeProps } from "./types";
import { flattenTree } from "./tree";

/** VaFileTree 的状态：展开集合（非受控）+ 选中（受控/非受控哨兵）+ 可见行 + roving focus */
export function useFileTree(props: FileTreeProps) {
  /* ---------- 展开集合 ---------- */
  const expanded = ref<Set<string>>(new Set());
  watch(
    () => props.tree,
    (tree) => {
      const next = new Set<string>();
      const depth = props.defaultExpandDepth ?? 1;
      const walk = (nodes: typeof tree, level: number) => {
        for (const n of nodes) {
          if (n.children?.length && level <= depth) {
            next.add(n.path);
            walk(n.children, level + 1);
          }
        }
      };
      walk(tree, 1);
      expanded.value = next;
    },
    { immediate: true },
  );

  function toggleDir(path: string, value?: boolean) {
    const next = new Set(expanded.value);
    const target = value ?? !next.has(path);
    if (target) next.add(path);
    else next.delete(path);
    expanded.value = next;
    return target;
  }

  /* ---------- 选中（受控优先，touched 哨兵回落 defaultSelected） ---------- */
  const touched = ref(false);
  const innerSelected = ref<string | undefined>(props.defaultSelected);
  const currentSelected = computed(() =>
    props.selected !== undefined || touched.value ? props.selected : innerSelected.value,
  );

  function select(path: string | undefined) {
    touched.value = true;
    innerSelected.value = path;
    return path;
  }

  /* ---------- 可见行 ---------- */
  const rows = computed(() => flattenTree(props.tree, (p) => expanded.value.has(p)));

  /* ---------- roving focus：↑↓ 移动的"当前项" ---------- */
  const focusedPath = ref<string | undefined>(rows.value[0]?.node.path);
  watch(rows, (r) => {
    if (!r.some((x) => x.node.path === focusedPath.value)) focusedPath.value = r[0]?.node.path;
  });

  function moveFocus(delta: number) {
    const list = rows.value;
    const idx = list.findIndex((r) => r.node.path === focusedPath.value);
    const next = list[Math.min(list.length - 1, Math.max(0, idx + delta))];
    if (next) focusedPath.value = next.node.path;
  }

  /** 聚焦当前项（keydown 后由模板 focus()） */
  function isActive(path: string) {
    return focusedPath.value === path;
  }

  return {
    expanded,
    toggleDir,
    currentSelected,
    select,
    rows,
    focusedPath,
    moveFocus,
    isActive,
  };
}
